'use strict';
window.ZumiImages=function({state,$,page,clean,link,runTask,tell,download,safeName,exportCoordinates,isBusy,isCancelled}){
 let zipper=null;const root=new URL('.',location.href);
 function options(){return{format:$('imageFormat').value,quality:Math.max(.4,Math.min(1,Number($('jpgQuality').value)/100)),scope:$('imageScope').value,coordinates:$('imageCoordinates').checked};}
 function targets(o){const a=o.scope==='page'?(page()?[page()]:[]):state.pages;if(!a.length)throw Error('Carga imágenes primero.');const missing=a.find(p=>!p.blob);if(missing)throw Error('Carga el raw de '+missing.filename+' antes de exportar.');return a;}
 function names(pages,format){const seen=new Set();return pages.map(p=>{const stem=safeName(p.filename.replace(/\.[^.]+$/,'')),ext=format==='png'?'.png':'.jpg';let n=stem+ext,i=2;while(seen.has(n.toLowerCase()))n=stem+'_'+i+++ext;seen.add(n.toLowerCase());return n;});}
 function update(){const jpg=$('imageFormat').value==='jpeg';$('jpgQualityLabel').hidden=!jpg;$('jpgQualityValue').textContent=$('jpgQuality').value+'%';$('saveImageFolder').hidden=typeof showDirectoryPicker!=='function';$('imageFolderHint').hidden=typeof showDirectoryPicker==='function';}
 function open(){if(isBusy())return;if(!state.pages.length)return tell('Carga imágenes primero.');update();$('imageExportDialog').showModal();}
 $('exportImages').onclick=open;$('cleanExportImages').onclick=open;$('imageFormat').onchange=update;$('jpgQuality').oninput=update;
 async function blobFor(p,o){const c=await clean.compose(p);try{const g=c.getContext('2d');if(o.format==='jpeg'){g.globalCompositeOperation='destination-over';g.fillStyle='white';g.fillRect(0,0,c.width,c.height);g.globalCompositeOperation='source-over';}
   const blob=await new Promise(resolve=>c.toBlob(resolve,o.format==='png'?'image/png':'image/jpeg',o.quality));if(!blob||!blob.size||blob.type!==(o.format==='png'?'image/png':'image/jpeg'))throw Error('El navegador no pudo exportar '+p.filename+' a tamaño completo. Guarda el proyecto y prueba en escritorio.');return blob;
  }finally{c.width=c.height=0;}
 }
 async function build(o,onImage=()=>{}){const selected=targets(o),filenames=names(selected,o.format),all=exportCoordinates(),coords=[],images=[];
  for(let i=0;i<selected.length;i++){if(isCancelled())throw Error('Operación detenida.');const p=selected[i];tell('Preparando imagen '+(i+1)+' / '+selected.length+' · '+p.filename);const blob=await blobFor(p,o);if(isCancelled())throw Error('Operación detenida.');const name=filenames[i],coordinate=all[state.pages.indexOf(p)];coords.push({...coordinate,filename:name,full_path:name});images.push({name,type:blob.type,blob});await onImage(images.at(-1));}
  return{name:state.name,pages:coords,images};
 }
 function coordinates(data){return new Blob([JSON.stringify(data.pages,null,2)],{type:'application/json;charset=utf-8'});}
 async function jszip(){if(window.JSZip)return window.JSZip;if(!zipper)zipper=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL('vendor/jszip.min.js',root);s.onload=()=>resolve(window.JSZip);s.onerror=()=>{zipper=null;reject(Error('Falta vendor/jszip.min.js. Extrae todo el ZIP.'));};document.head.append(s);});return zipper;}
 $('downloadImages').onclick=()=>{const o=options();$('imageExportDialog').close();runTask(async()=>{const data=await build(o);if(data.images.length===1&&!o.coordinates){download(data.images[0].blob,data.images[0].name);tell('Imagen descargada.');return;}const Zip=await jszip(),zip=new Zip();for(const f of data.images)zip.file(f.name,f.blob);if(o.coordinates)zip.file(safeName(state.name)+'_Coordenadas.json',coordinates(data));const result=await zip.generateAsync({type:'blob',compression:'STORE'});if(isCancelled())return;download(result,safeName(state.name)+'_Limpias.zip');tell(data.images.length+' imágenes exportadas'+(o.coordinates?' con coordenadas.':'.'));});};
 async function newFolder(parent){const base=safeName(state.name)+'_Limpias';for(let i=0;i<10000;i++){const name=base+(i?'_'+(i+1):'');try{await parent.getDirectoryHandle(name);continue;}catch(e){if(e.name!=='NotFoundError')throw e;}return parent.getDirectoryHandle(name,{create:true});}throw Error('No pude crear una carpeta nueva. Elige otra ubicación.');}
 async function write(folder,name,blob){const handle=await folder.getFileHandle(name,{create:true}),stream=await handle.createWritable();try{await stream.write(blob);await stream.close();}catch(e){await stream.abort().catch(()=>{});throw e;}}
 $('saveImageFolder').onclick=async()=>{const o=options();let parent;try{targets(o);parent=await showDirectoryPicker({mode:'readwrite'});}catch(e){if(e.name!=='AbortError')tell(e.message);return;}$('imageExportDialog').close();runTask(async()=>{const folder=await newFolder(parent);let written=0;try{const data=await build(o,async f=>{await write(folder,f.name,f.blob);written++;});if(o.coordinates)await write(folder,safeName(state.name)+'_Coordenadas.json',coordinates(data));tell(written+' imágenes guardadas en '+folder.name+'.');}catch(e){throw Error(e.message+(written?' Se conservaron '+written+' imágenes ya guardadas en '+folder.name+'.':''));}});};
 $('sendCleanTyper').onclick=()=>{const o=options();try{targets(o);}catch(e){tell(e.message);return;}if(!link.open())return;$('imageExportDialog').close();runTask(async()=>{const data=await build(o);if(isCancelled())return;tell('Enviando imágenes y coordenadas a Zumi Typer…');await link.send(data);tell('Zumi Typer recibió '+data.images.length+' imágenes y sus coordenadas. Elige tu carpeta de estilos y pulsa Pegar lote.');});};
 return{open,build,blobFor,names};
};
